py::array_t<double> vectorizedPayoff(
    py::array_t<double> spots,
    double strike) {
  auto buf = spots.request();
  auto result =
    py::array_t<double>(buf.shape);
  auto resBuf = result.request();
  const double* in =
    static_cast<const double*>(buf.ptr);
  double* out =
    static_cast<double*>(resBuf.ptr);
  for (ssize_t i=0;i<buf.shape[0];++i)
    out[i] = std::max(in[i]-strike, 0.0);
  return result;
}
